with cleaned as (select *, round(budget, 0) budget_rounded, lower(location) location_lower, coalesce(dept_name, 'N/A') dept_name_filled from departments where location is not distinct from 'Chiang Mai' and dept_name not in ('Legal', 'Sales', 'Marketing')) select s.id, s.dept_name, s.budget_rounded, s.dept_name_filled, latest.hire_date, latest.employee_job_title from cleaned s left join lateral (select c.hire_date, c.job_title as employee_job_title from employees c where c.dept_id = s.id order by c.salary desc, c.id desc limit 1) latest on true;
